const pageMeta={
  home:'Defense products, precision-manufacturing heritage, sustainability, and official contact information from SNT Defense.',
  firearms:'Explore K13, K2, K2C1, K2C, K14, and STSM21 specifications from SNT’s published defense catalog.',
  about:'Learn about SNT’s precision-manufacturing history, values, certifications, and global business sites.',
  support:'Review SNT’s published ESG, human-rights, ethics, quality, and environmental commitments.',
  contact:'Contact SNT Defense in Las Vegas or the SNT Motiv defense division in Busan for product inquiries.'
};
function setPage(name,title,render){
  document.title=`${title} | SNT Defense`;
  document.querySelector('meta[name="description"]').content=pageMeta[name]||'SNT Defense company and product information.';
  const canonical=`${location.origin}${location.pathname}`;
  document.querySelector('link[rel="canonical"]').href=canonical;
  document.querySelector('meta[property="og:title"]').content=`${title} | SNT Defense`;
  document.querySelector('meta[property="og:description"]').content=pageMeta[name]||'SNT Defense company and product information.';
  document.querySelector('meta[property="og:url"]').content=canonical;
  document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===name));
  content.innerHTML=render;
}
function home(){setPage('home','Home',`
  <section class="hero hero--home"><div class="hero__inner"><h1>Global Defense Company</h1><p>Creating the future with trust, precision and technology.</p></div></section>
  <section class="section" id="business"><div class="wrap"><div class="section-kicker">Explore SNT</div><h2>Precision with purpose</h2><p class="lead">SNT’s defense business is supported by more than four decades of precision manufacturing, quality management, and international operations.</p><div class="business-grid">
    ${card('01','Firearms','67e23e1acf7452f77d1fc6a7_mbis_mimg04.jpg','Explore the current rifle, carbine, sniper-rifle and submachine-gun lineup.','/firearms')}
    ${card('02','Heritage','67e1e1b51adec107213027c7_mbis_tit.jpg','Trace milestones from the first small-caliber defense programs to today.','/about#history')}
    ${card('03','Quality','67e2be4b977fcfc8d1bf5e6f_mbis_img05.jpg','Review the quality systems and certifications behind production.','/support#quality')}
    ${card('04','ESG','67e1e7227c92b6302c2bbf6c_mbis_img02.jpg','Read the published environmental, social, and governance priorities.','/support#esg')}
    ${card('05','Global Sites','67e2be948a581e9d0183a6e1_mbis_img06.jpg','Find headquarters and overseas business locations.','/about#sites')}
    ${card('06','Contact','67e2bef1c5a78aef862866cd_mbis_img07.jpg','Reach the U.S. office or the defense-product team in Korea.','/contact')}
  </div></div></section>
  <section class="split"><div class="split__image" role="img" aria-label="SNT precision manufacturing facility"></div><div class="split__content"><div class="section-kicker">Since 1981</div><h2>A heritage of precision</h2><p>SNT Motiv traces its manufacturing heritage to Daewoo Precision Industries, founded in December 1981. Its published history records the development of Korean small-caliber firearms beginning in 1982.</p><a class="button" href="/about#history">Explore the history</a></div></section>`)}
function card(no,title,img,text,href){return `<a class="business-card" href="${href}" style="background-image:url('${A+img}')"><small>${no}</small><h3>${title}</h3><p>${text}</p><span class="card-link">Explore →</span></a>`}
function firearms(){
  const requested=location.hash.slice(1).toLowerCase();
  const selected=weapons.find(item=>item.id===requested)||weapons.find(item=>item.id==='k2');
  setPage('firearms',selected.name,`
    <section class="hero hero--sub hero--firearms"><div class="hero__inner"><div class="hero-eyebrow">Firearms</div><h1>${selected.category}</h1><p>${selected.name}</p></div></section>
    <nav class="category-bar" aria-label="Firearm models" role="tablist">${weapons.map(item=>`<button type="button" role="tab" aria-selected="${item.id===selected.id}" class="${item.id===selected.id?'active':''}" data-firearm="${item.id}">${item.tab}</button>`).join('')}</nav>
    ${productPanel(selected)}`);
  document.querySelectorAll('[data-firearm]').forEach(button=>button.addEventListener('click',()=>selectFirearm(button.dataset.firearm)));
}
function productPanel(item){return `<section class="product" id="${item.id}" aria-live="polite"><div class="wrap"><div class="product-heading"><div><div class="section-kicker">${item.category}</div><h2>${item.name}</h2><p class="product-subtitle">${item.caliber}</p></div><span class="product-count">${String(weapons.indexOf(item)+1).padStart(2,'0')} / ${String(weapons.length).padStart(2,'0')}</span></div><div class="product-image-stage"><img class="product-shot" src="${item.image}" alt="${item.alt}"></div><div class="specs">${item.specs.map(spec=>`<div class="spec"><span>${spec[0]}</span><strong>${spec[1]}</strong></div>`).join('')}</div><p class="product-source">Specifications and imagery: <a href="https://www.sntmotiv.com/eng/business/defense.html" target="_blank" rel="noopener">SNT Motiv defense catalog</a>.</p></div></section>`}
function selectFirearm(id){
  if(!weapons.some(item=>item.id===id))return;
  history.pushState({},'',`${location.pathname}#${id}`);
  firearms();
  document.querySelector('.category-bar').scrollIntoView({block:'start'});
}
function about(){setPage('about','About',`
  <section class="hero hero--sub hero--about"><div class="hero__inner"><h1>About Us</h1><p>Audacious challenges. A heritage of precision.</p></div></section>
  <nav class="category-bar" aria-label="About sections"><a href="#overview">Overview</a><a href="#history">History</a><a href="#values">Values</a><a href="#certifications">Certifications</a><a href="#sites">Business Sites</a></nav>
  <section class="section" id="overview"><div class="wrap intro-grid"><div><div class="section-kicker">Overview</div><h2>Built on precision technology</h2><p class="lead">SNT Motiv has developed and produced defense products and automotive core components since its founding in December 1981. The company describes a global footprint spanning Asia, Europe, and the Americas.</p><p>This rebuild presents public information from SNT Motiv alongside the SNT Defense identity used by the original U.S. website. The exact corporate relationship remains subject to company confirmation.</p><a class="text-link" href="https://www.sntmotiv.com/eng/about/overview.html" target="_blank" rel="noopener">Official company overview →</a></div><img src="${A+'67e41e3491374725fefddc81_overview_topimg.jpg'}" alt="SNT precision manufacturing facility"></div></section>
  <section class="section section--navy" id="history"><div class="wrap"><div class="section-kicker">Selected milestones</div><h2>More than four decades of development</h2><div class="timeline"><article><time>1981</time><h3>Daewoo Precision Industries founded</h3><p>The company’s published history begins in December 1981.</p></article><article><time>1982</time><h3>Small-caliber firearms development</h3><p>Development programs began for Korea’s Ministry of National Defense, followed by Korean small-caliber firearms.</p></article><article><time>1999</time><h3>Defense quality system</h3><p>The company records certification for defense quality systems.</p></article><article><time>2006</time><h3>S&amp;T Daewoo</h3><p>The company name changed to S&amp;T Daewoo Co., Ltd.</p></article><article><time>2012</time><h3>S&amp;T Motiv</h3><p>The organization adopted the S&amp;T Motiv name.</p></article><article><time>2021</time><h3>SNT Motiv</h3><p>The company was renamed SNT Motiv Co., Ltd.</p></article></div><a class="button" href="https://www.sntmotiv.com/eng/about/history.html" target="_blank" rel="noopener">View official history</a></div></section>
  <section class="section section--soft" id="values"><div class="wrap"><div class="section-kicker">Culture</div><h2>Spirit and culture</h2><div class="facts"><div class="fact"><strong>Field management</strong><span>Find practical solutions where the work is performed.</span></div><div class="fact"><strong>Integrity</strong><span>Act transparently and follow sound principles.</span></div><div class="fact"><strong>Future orientation</strong><span>Turn proactive thinking into timely action.</span></div></div></div></section>
  <section class="section" id="certifications"><div class="wrap"><div class="section-kicker">Management systems</div><h2>Published certifications</h2><p class="lead">SNT Motiv publicly lists certifications and accreditations across quality, environmental, safety, defense, calibration, testing, and process management.</p><div class="chip-list"><span>ISO 9001</span><span>IATF 16949</span><span>ISO 14001</span><span>ISO 45001</span><span>Defense Quality Management</span><span>Calibration Laboratory</span><span>Testing Laboratory</span><span>CMMI</span></div><p class="source-note">Applicability to individual products or U.S. operations must be confirmed. <a href="https://www.sntmotiv.com/eng/about/certificate.html" target="_blank" rel="noopener">Official certification list →</a></p></div></section>
  <section class="section section--soft" id="sites"><div class="wrap"><div class="section-kicker">Business sites</div><h2>Global operations</h2><div class="location-grid"><article><small>Headquarters</small><h3>Busan, South Korea</h3><p>363, Yeoraksongjeong-ro<br>Cheolma-myeon, Gijang-gun<br>Busan, South Korea</p><p><a href="tel:+82515092114">+82-51-509-2114</a></p></article><article><small>United States</small><h3>SNT America</h3><p>3331 West Big Beaver Rd, Suite 108<br>Troy, MI 48084, USA</p><p><a href="tel:+12486496592">+1-248-649-6592</a></p></article><article><small>SNT Defense website</small><h3>Las Vegas</h3><p>1850 E Maule Ave<br>Las Vegas, NV 89119</p><p class="source-note">Address retained from the original SNT Defense website; entity and office function require confirmation.</p></article></div><a class="text-link" href="https://www.sntmotiv.com/eng/about/facilities02.html" target="_blank" rel="noopener">Official overseas business sites →</a></div></section>`)}
function support(){setPage('support','Support',`
  <section class="hero hero--sub hero--support"><div class="hero__inner"><h1>Support</h1><p>We create a sustainable future for everyone.</p></div></section>
  <nav class="category-bar" aria-label="Sustainability sections"><a href="#esg">ESG</a><a href="#human-rights">Human Rights</a><a href="#ethics">Ethics</a><a href="#quality">Quality</a><a href="#environment">Environment</a></nav>
  <section class="section" id="esg"><div class="wrap"><div class="section-kicker">Sustainability</div><h2>ESG Management</h2><p class="lead">SNT Motiv states that its sustainability program combines economic and social value with field management, integrity, and transparency.</p><div class="pillars"><article><b>E</b><h3>Environment</h3><p>Carbon-reduction planning, hazardous-substance reduction, energy efficiency, environmental management, and occupational safety.</p></article><article><b>S</b><h3>Social</h3><p>Scholarships, community support, disability-welfare programs, and supplier ESG capability development.</p></article><article><b>G</b><h3>Governance</h3><p>Transparent and ethical management, respect for human rights and diversity, and long-term strategic planning.</p></article></div><a class="text-link" href="https://www.sntmotiv.com/eng/sustainability/esg.html" target="_blank" rel="noopener">Official ESG page →</a></div></section>
  <section class="section section--soft" id="human-rights"><div class="wrap"><div class="section-kicker">People</div><h2>Human Rights</h2><p class="lead">The published Human Rights Management Charter commits to human dignity, applicable labor law, and internationally recognized standards.</p><div class="commitment-grid"><p>No discrimination; respect for diversity.</p><p>Freedom of association and collective bargaining.</p><p>Safe and hygienic working conditions.</p><p>No forced labor or child labor.</p><p>Respect for customers, partners, and communities.</p><p>Protection of personal information and transparent disclosure.</p></div><a class="text-link" href="https://www.sntmotiv.com/eng/sustainability/people.html" target="_blank" rel="noopener">Read the official charter →</a></div></section>
  <section class="section" id="ethics"><div class="wrap"><div class="section-kicker">Conduct</div><h2>Ethical Management</h2><div class="ethics-banner"><p>SNT states that it works to establish an ethical corporate culture through compliance with law and ethical standards.</p></div><div class="principles"><article class="principle"><b>01</b><h3>Workplace discipline</h3><p>Protect confidential information and use company resources responsibly.</p></article><article class="principle"><b>02</b><h3>Respect at work</h3><p>Maintain a workplace free from harassment and discrimination.</p></article><article class="principle"><b>03</b><h3>Fair partnerships</h3><p>Avoid conflicts of interest and conduct that undermines fair trade.</p></article></div></div></section>
  <section class="section section--navy" id="quality"><div class="wrap"><div class="section-kicker">Quality management</div><h2>Continuous improvement</h2><p class="lead">SNT Motiv publishes a “Zero Defect” quality policy supported by management systems intended to reflect legal, regulatory, and customer requirements.</p><div class="quality-grid"><article><strong>ISO 9001</strong><span>Quality management</span></article><article><strong>IATF 16949</strong><span>Automotive quality</span></article><article><strong>Defense Quality</strong><span>Defense-system certification</span></article><article><strong>ISO/IEC 17025</strong><span>Calibration and testing</span></article></div><a class="button" href="https://www.sntmotiv.com/eng/sustainability/quality.html" target="_blank" rel="noopener">Official quality policy</a></div></section>
  <section class="section" id="environment"><div class="wrap"><div class="section-kicker">Environment</div><h2>Prevention, compliance, improvement</h2><p class="lead">The published environmental rules emphasize prevention, legal and safety compliance, pollution reduction, employee training, and transparent disclosure.</p><div class="numbered-list"><p><b>01</b><span>Prevent environmental impacts and accidents throughout business activities.</span></p><p><b>02</b><span>Follow applicable environmental laws, safety rules, and internal standards.</span></p><p><b>03</b><span>Continuously reduce pollution and environmental or safety risks.</span></p><p><b>04</b><span>Build employee capability through training and participation.</span></p><p><b>05</b><span>Publish management rules to support transparency.</span></p></div><div class="certificate-feature"><a class="certificate-preview" href="/assets/certifications/ISO14001.pdf" target="_blank" rel="noopener" aria-label="Open the archived SNT Motiv ISO 14001 certificate PDF"><img src="/assets/certifications/iso-14001-certificate.jpg" alt="English SNT Motiv ISO 14001 environmental management system certificate issued in 2021"></a><div class="certificate-copy"><div class="section-kicker">Official document archive</div><h3>ISO 14001:2015</h3><p>The Korean Foundation for Quality certified the environmental management system at SNT Motiv’s head office and Busan factory. The documented scope expressly includes the design, development, and production of firearms.</p><dl class="certificate-facts"><div><dt>Certificate</dt><dd>EAC-00867-(01)</dd></div><div><dt>Issued</dt><dd>March 4, 2021</dd></div><div><dt>Document expiry</dt><dd>December 22, 2021</dd></div><div><dt>Initial registration</dt><dd>December 23, 1997</dd></div></dl><div class="archive-warning"><strong>Archived certificate</strong><span>This official download is historical and does not establish current certification status. A current certificate should be obtained before making an active-certification claim.</span></div><a class="button button--dark" href="/assets/certifications/ISO14001.pdf" target="_blank" rel="noopener">View certificate PDF</a><a class="text-link" href="https://www.sntmotiv.com/eng/sustainability/environment.html" target="_blank" rel="noopener">Official environmental page →</a></div></div></div></section>`)}
function contact(){setPage('contact','Contact',`
  <section class="hero hero--sub hero--contact"><div class="hero__inner"><h1>Contact Us</h1><p>Questions, feedback or partnership inquiries—we would be glad to hear from you.</p></div></section>
  <section class="section"><div class="wrap contact-grid"><aside><div class="contact-card"><div class="section-kicker">United States</div><h2>Las Vegas</h2><p>1850 E Maule Ave<br>Las Vegas, NV 89119</p><p class="contact-caveat">Address retained from the original SNT Defense website. Please confirm availability before visiting.</p></div><div class="contact-card contact-card--light"><div class="section-kicker">Defense products</div><h2>Busan</h2><p>363, Yeoraksongjeong-ro<br>Cheolma-myeon, Gijang-gun<br>Busan 46002, Republic of Korea</p><p><a href="tel:+82515092188">+82-(0)51-509-2188</a><br><a href="mailto:charles@sntmotiv.com">charles@sntmotiv.com</a></p><small>Published in the SNT Motiv defense catalog.</small></div></aside><form id="contact-form"><div class="section-kicker">Email inquiry</div><h2>Prepare your message</h2><p class="form-intro">Submitting opens your email application with a prepared message. Nothing is stored by this website.</p><div class="form-grid"><label>First name<input name="firstName" autocomplete="given-name" required></label><label>Last name<input name="lastName" autocomplete="family-name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Company<input name="company" autocomplete="organization"></label><label class="full">Inquiry type<select name="inquiry"><option>Product information</option><option>Business partnership</option><option>Media inquiry</option><option>Service or support</option><option>Other</option></select></label><label class="full">Message<textarea name="message" required minlength="10"></textarea></label><label class="consent full"><input type="checkbox" name="consent" required><span>I understand this opens my email application and that my message will be handled by the recipient’s email systems.</span></label><div class="full"><button class="button" type="submit">Open email draft</button></div></div><p class="form-note" id="form-status" role="status" aria-live="polite">Your information remains on this device until you choose to send the email.</p></form></div></section>`);
  document.querySelector('#contact-form').addEventListener('submit',prepareInquiry);}
function prepareInquiry(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const name=`${data.get('firstName')} ${data.get('lastName')}`.trim();const subject=`SNT Defense — ${data.get('inquiry')}`;const body=[`Name: ${name}`,`Email: ${data.get('email')}`,`Company: ${data.get('company')||'Not provided'}`,`Inquiry: ${data.get('inquiry')}`,'',data.get('message')].join('\n');document.querySelector('#form-status').textContent='Your email application should open with the message prepared. Review it before sending.';location.href=`mailto:charles@sntmotiv.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}
function notFound(){setPage('', 'Page not found',`<section class="not-found"><div><div class="section-kicker">404</div><h1>Page not found</h1><p>The address may be outdated, or the page may have moved.</p><a class="button" href="/">Return home</a></div></section>`)}
function render(){const path=location.pathname.replace(/\/$/,'')||'/';(routes[path]||notFound)();requestAnimationFrame(()=>{updateCategoryActive();if(location.hash)scrollToHash(location.hash);else window.scrollTo(0,0);});}
function scrollToHash(hash,focus=false){let target;try{target=document.querySelector(hash)}catch{return}if(!target)return;target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});if(focus){if(!target.hasAttribute('tabindex'))target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}}
function updateCategoryActive(){const links=[...document.querySelectorAll('.category-bar a')];const activeHash=location.hash||links[0]?.hash;links.forEach(link=>link.classList.toggle('active',link.hash===activeHash));}
document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin)return;event.preventDefault();const samePath=url.pathname===location.pathname;history.pushState({},'',url.pathname+url.hash);if(samePath&&url.hash&&document.querySelector(url.hash)){updateCategoryActive();scrollToHash(url.hash,link.classList.contains('skip-link'));}else{render();if(link.classList.contains('skip-link'))content.focus();}const nav=document.querySelector('#primary-nav');nav.classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');});
document.querySelector('.menu-toggle').addEventListener('click',event=>{const nav=document.querySelector('#primary-nav');const open=nav.classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open));});
addEventListener('popstate',render); addEventListener('hashchange',()=>{if(location.pathname.endsWith('/firearms'))render();else{updateCategoryActive();scrollToHash(location.hash);}}); render();
